# Frontend (Next.js)

The App Router shows the paginated frame inventory, version history, and DELTA
imports. Frame history links to the durable import job summary, which remains
available after row diagnostics expire.

Apollo Client sends browser GraphQL requests to the same-origin `/api/graphql` route.
Set `BFF_URL` to the BFF origin or full GraphQL URL. It defaults to
`http://127.0.0.1:4000` and Compose uses `http://bff:4000`. The existing
`/api/:path*` fallback forwards requests such as health checks to
`BACKEND_URL` (default `http://localhost:8080`).

## GraphQL operations

Use Node.js 22.18 or newer for code generation. Keep operations in `.graphql`
files under `src/`. Run `npm run codegen` after changing an operation or the
BFF schema. Codegen reads `../bff/schema/*.gql` from the checkout, so it can
run without a running BFF. Include `src/generated/graphql.ts` when committing
schema or operation changes. Run `npm run codegen:check` to verify that the
generated documents are current.

## Local development

Run `npm ci` and `npm run dev` from `src/frontend`. For local imports, run
Spring Boot and the BFF on the host and enable their local import settings.
Start the frontend with `npm run dev -- --hostname 127.0.0.1` for this flow.
See the [backend README](../backend/README.md) and [BFF README](../bff/README.md).
In **Imports**, enter the local operator token and select the CSV file.
The browser sends the file directly to the S3 URL with the signed headers.
Keep the frontend origin in the upload bucket's CORS configuration.

The frontend keeps the operator token in memory for this session. To reopen an
import, use its job ID or select the import link in a frame's version history.
Run `npm run lint` and `npm run build` to verify the frontend.

## Verify a DELTA import in the browser

Set `INVENTORY_IMPORT_LOCAL_TOKEN` in the repository root's `.env` to a value
generated by `openssl rand -hex 32`. From the repository root, start the local
stack with imports enabled.

```sh
docker compose up -d --build --wait
```

Use an empty local database for the counts below. Compose reuses its existing
database volume, so on a stack with inventory the first upload counts may vary.

1. Open **Imports** at <http://127.0.0.1:3000>. Enter the local operator token
   and upload [`inventory_frame.csv`](../../data/inventory_frame.csv).
   The completed job should show 1,000 applied and zero rejected.
2. Upload the same file again. The second job should show 1,000 unchanged
   and zero applied.
3. Open **Frames** and view an imported frame's version history. Its import job
   link should open the first job.
4. In a copy of the CSV, keep the header and one data row. Change that row's
   `status` to `INVALID` and upload the copy. The job should complete with one
   rejected row. **View row errors** should identify the invalid status.

For more cases, use the [test CSVs](../../data/import-cases/README.md) and their
expected results.
import asyncio
import logging
import os
import signal
from datetime import timedelta

from grpc import aio
from temporalio.client import Client
from temporalio.worker import Worker

from frameinventory.v1.import_worker_pb2_grpc import ImportWorkerStub

from .activities import ImportActivities
from .workflow import CsvImportWorkflow


async def main() -> None:
    logging.basicConfig(level=logging.INFO)
    stop = asyncio.Event()
    loop = asyncio.get_running_loop()
    for sig in (signal.SIGINT, signal.SIGTERM):
        loop.add_signal_handler(sig, stop.set)

    token = os.environ.get("INVENTORY_IMPORT_LOCAL_TOKEN")
    if not token:
        logging.info("Inventory import worker disabled. Set INVENTORY_IMPORT_LOCAL_TOKEN to enable it.")
        await stop.wait()
        return

    client = await Client.connect(
        os.environ.get("INVENTORY_IMPORT_DISPATCH_TEMPORAL_TARGET", "127.0.0.1:7233"),
        namespace=os.environ.get("INVENTORY_IMPORT_DISPATCH_TEMPORAL_NAMESPACE", "default"),
    )
    task_queue = os.environ.get("INVENTORY_IMPORT_DISPATCH_TASK_QUEUE", "inventory-import")
    async with aio.insecure_channel("127.0.0.1:9090") as backend:
        activities = ImportActivities(ImportWorkerStub(backend), token)
        async with Worker(
            client,
            task_queue=task_queue,
            workflows=[CsvImportWorkflow],
            activities=[activities.stage, activities.apply, activities.fail],
            graceful_shutdown_timeout=timedelta(seconds=20),
        ):
            logging.info("Inventory import worker polling %s", task_queue)
            await stop.wait()


if __name__ == "__main__":
    asyncio.run(main())
package com.global.ct.frameinventory.inventoryimport;

import java.net.InetSocketAddress;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.util.regex.Pattern;

import io.grpc.Context;
import io.grpc.Contexts;
import io.grpc.Grpc;
import io.grpc.Metadata;
import io.grpc.ServerCall;
import io.grpc.ServerCallHandler;
import io.grpc.ServerInterceptor;
import io.grpc.Status;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.core.env.Environment;
import org.springframework.core.env.Profiles;
import org.springframework.stereotype.Component;

/** Service-scoped authentication for the local import exercise. */
@Component
public final class LocalImportIdentity implements ServerInterceptor {
    private static final Metadata.Key<String> AUTHORIZATION =
            Metadata.Key.of("authorization", Metadata.ASCII_STRING_MARSHALLER);
    private static final Context.Key<String> OPERATOR = Context.key("import-operator");
    private static final Pattern TOKEN = Pattern.compile("[a-f0-9]{64}");

    private final boolean enabled;
    private final byte[] expectedAuthorization;

    public LocalImportIdentity(
            Environment environment,
            @Value("${inventory.import.local-token:}") String token) {
        enabled = environment.acceptsProfiles(Profiles.of("local-import"));
        if (enabled && !TOKEN.matcher(token).matches()) {
            throw new IllegalArgumentException("Local import requires a 64-character lowercase hex token");
        }
        expectedAuthorization = ("Bearer " + token).getBytes(StandardCharsets.US_ASCII);
    }

    public static String requireOperator() {
        String operator = OPERATOR.get();
        if (operator == null) {
            throw Status.UNAUTHENTICATED.asRuntimeException();
        }
        return operator;
    }

    public static void requireJobOwner(String owner) {
        if (!requireOperator().equals(owner)) {
            throw Status.PERMISSION_DENIED.asRuntimeException();
        }
    }

    @Override
    public <ReqT, RespT> ServerCall.Listener<ReqT> interceptCall(
            ServerCall<ReqT, RespT> call, Metadata headers, ServerCallHandler<ReqT, RespT> next) {
        if (!enabled) {
            call.close(Status.UNAVAILABLE.withDescription("Local imports are disabled"), new Metadata());
            return new ServerCall.Listener<>() {};
        }
        var peer = call.getAttributes().get(Grpc.TRANSPORT_ATTR_REMOTE_ADDR);
        String authorization = headers.get(AUTHORIZATION);
        if (!(peer instanceof InetSocketAddress socket) || socket.getAddress() == null
                || !socket.getAddress().isLoopbackAddress() || authorization == null
                || !MessageDigest.isEqual(expectedAuthorization, authorization.getBytes(StandardCharsets.US_ASCII))) {
            call.close(Status.UNAUTHENTICATED, new Metadata());
            return new ServerCall.Listener<>() {};
        }
        return Contexts.interceptCall(Context.current().withValue(OPERATOR, "local-import-operator"),
                call, headers, next);
    }
}
